import os, json, math, wave
import numpy as np

SR = 44100
ROOT = '/workspace/work'
SND = os.path.join(ROOT, 'sounds')
os.makedirs(SND, exist_ok=True)
rng = np.random.default_rng(0xC1PH3R if False else 0xC1F3A)

# ---------- Original sample synthesis ----------
def t_axis(dur):
    return np.arange(int(round(dur * SR)), dtype=np.float64) / SR

def fade_edges(x, attack=0.003, release=0.015):
    n = len(x)
    a = min(n, int(attack * SR)); r = min(n, int(release * SR))
    if a > 0: x[:a] *= np.sin(np.linspace(0, np.pi/2, a))**2
    if r > 0: x[-r:] *= np.cos(np.linspace(0, np.pi/2, r))**2
    return x

def norm(x, peak=0.82):
    m = np.max(np.abs(x))
    return x * (peak / m) if m > 1e-12 else x

def save_wav(name, x, peak=0.82):
    x = fade_edges(np.asarray(x, dtype=np.float64), 0.002, 0.012)
    x = norm(x, peak)
    path = os.path.join(SND, name + '.wav')
    with wave.open(path, 'wb') as w:
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(SR)
        w.writeframes(np.round(np.clip(x, -1, 1)*32767).astype('<i2').tobytes())
    return path

def filt_noise(n, lo=0, hi=None):
    if hi is None: hi = SR/2
    z = rng.normal(0, 1, n)
    f = np.fft.rfftfreq(n, 1/SR)
    Z = np.fft.rfft(z)
    # Smooth-edged brick filters, entirely offline synthesis.
    lowmask = np.clip((f-lo)/max(80.0, lo*0.12+1), 0, 1) if lo else np.ones(n//2+1)
    himask = np.clip((hi-f)/max(100.0, hi*0.08), 0, 1)
    Z *= lowmask * himask
    y = np.fft.irfft(Z, n)
    return y / (np.std(y)+1e-9)

def pluck():
    t=t_axis(0.48); f=261.625565
    x=np.zeros_like(t)
    phases=rng.uniform(0,2*np.pi,14)
    for h in range(1,15):
        amp=(1/(h**1.12))*np.exp(-t*(1.2+0.34*h))
        x += amp*np.sin(2*np.pi*f*h*t + phases[h-1])
    # Two quiet, slightly detuned strands give the attack a glassy width.
    x += 0.18*np.sin(2*np.pi*f*1.003*t)*np.exp(-5*t)
    x += 0.12*filt_noise(len(t),1800,9000)*np.exp(-75*t)
    env=(1-np.exp(-t*550))*np.exp(-4.8*t)
    return x*env

def lead():
    t=t_axis(1.02); f=523.251131
    vib=0.0028*np.sin(2*np.pi*5.4*t)*(1-np.exp(-8*t))
    phase=2*np.pi*f*(t + vib/(2*np.pi*5.4))
    x=np.zeros_like(t)
    # Reedy pulse/saw hybrid: solid fundamental, restrained upper harmonics.
    for h in range(1,13):
        amp=1/(h**1.42)
        if h%2: amp*=1.18
        x += amp*np.sin(h*phase + 0.11*h)
    x += 0.24*np.sin(2*np.pi*f*1.002*t+0.4)
    x += 0.16*np.sin(2*np.pi*f*0.998*t+1.1)
    env=(1-np.exp(-t*420))*(0.72+0.28*np.exp(-t*18))*np.exp(-1.65*t)
    rel=np.clip((1.02-t)/0.20,0,1)
    return x*env*rel

def bass():
    t=t_axis(0.38); f=65.406391
    phase=2*np.pi*f*(t + 0.0025*(1-np.exp(-t*35)))
    x=np.sin(phase)+0.40*np.sin(2*phase)+0.22*np.sin(3*phase)+0.11*np.sin(4*phase)
    x+=0.07*np.sin(5*phase)+0.04*np.sin(6*phase)
    x=np.tanh(x*1.25)
    env=(1-np.exp(-t*700))*np.exp(-3.1*t)*(0.88+0.12*np.exp(-t*15))
    return x*env

def pad():
    t=t_axis(1.62); f=261.625565
    x=np.zeros_like(t)
    for det,weight in [(0.997,0.30),(1.0,0.52),(1.003,0.30)]:
        ph=2*np.pi*f*det*t
        for h in range(1,8):
            x += weight/(h**1.65)*np.sin(h*ph+0.17*h)
    # Barely audible airy component, shaped rather than a static noise loop.
    x += 0.025*filt_noise(len(t),900,4200)*(0.6+0.4*np.sin(2*np.pi*0.7*t)**2)
    env=(1-np.exp(-t*16))*(0.90+0.10*np.cos(2*np.pi*0.45*t))
    env*=np.clip((1.62-t)/0.43,0,1)
    return x*env

def bell():
    t=t_axis(0.92); f=523.251131
    x=np.zeros_like(t)
    for ratio,amp,dec,ph in [(1,1,3.3,0),(2.01,0.42,5.2,0.4),(3.97,0.20,7.8,1.2),(6.08,0.11,10.5,0.7),(8.9,0.06,14,1.8)]:
        x += amp*np.sin(2*np.pi*f*ratio*t+ph)*np.exp(-dec*t)
    env=1-np.exp(-t*900)
    return x*env

def kick():
    t=t_axis(0.38)
    phase=2*np.pi*(47*t + (165-47)*0.022*(1-np.exp(-t/0.022)))
    body=np.sin(phase)*np.exp(-8.0*t)
    sub=0.32*np.sin(2*np.pi*47*t)*np.exp(-10*t)
    click=0.12*filt_noise(len(t),2500,10500)*np.exp(-95*t)
    return np.tanh((body+sub+click)*1.65)

def snare():
    t=t_axis(0.31)
    noise=0.72*filt_noise(len(t),650,10500)*np.exp(-15*t)
    body=0.45*np.sin(2*np.pi*(178*t+8*(1-np.exp(-t*35))))*np.exp(-18*t)
    clap=np.zeros_like(t)
    nz=filt_noise(len(t),1100,9000)
    for delay,amp in [(0,0.35),(0.011,0.25),(0.023,0.18)]:
        tt=np.maximum(0,t-delay); clap+=amp*nz*np.exp(-42*tt)*(t>=delay)
    return noise+body+clap

def hat(open_=False):
    dur=0.34 if open_ else 0.095
    t=t_axis(dur)
    n=filt_noise(len(t),5600,15500)
    metallic=np.zeros_like(t)
    for f in [6321,7917,9343,11251]: metallic+=0.10*np.sin(2*np.pi*f*t)
    dec=10 if open_ else 43
    return (0.75*n+metallic)*np.exp(-dec*t)*(1-np.exp(-t*1000))

def shaker():
    t=t_axis(0.14); n=filt_noise(len(t),3200,12500)
    env=np.exp(-24*t)*(0.65+0.35*np.sin(2*np.pi*31*t)**2)
    return n*env

def crash():
    t=t_axis(1.35)
    n1=filt_noise(len(t),2800,16000)
    n2=filt_noise(len(t),700,7500)
    shimmer=np.zeros_like(t)
    for f in [4173,5411,6979,8713]: shimmer+=0.07*np.sin(2*np.pi*f*t+rng.uniform(0,6.28))
    env=(1-np.exp(-t*900))*np.exp(-3.4*t)
    return (0.72*n1+0.22*n2+shimmer)*env

def riser():
    t=t_axis(1.58); u=t/1.58
    n=filt_noise(len(t),1200,14500)
    # Rising sine cluster plus increasingly bright amplitude-modulated noise.
    phase=2*np.pi*(170*t+520*t*t)
    tone=np.sin(phase)+0.35*np.sin(phase*1.498)
    gate=0.55+0.45*np.sin(2*np.pi*(5*t+7*t*t))**2
    env=(u**1.7)*np.clip((1.58-t)/0.035,0,1)
    return (0.32*tone+0.65*n*gate)*env

def stab():
    t=t_axis(0.25); f=261.625565
    x=np.zeros_like(t)
    for h in range(1,11): x+=(1/h**1.1)*np.sin(2*np.pi*f*h*t+0.2*h)
    env=(1-np.exp(-t*800))*np.exp(-16*t)
    return np.tanh(x)*env

def tom():
    t=t_axis(0.30)
    ph=2*np.pi*(130.8128*t+85*0.025*(1-np.exp(-t/0.025)))
    return (np.sin(ph)+0.20*np.sin(2*ph))*np.exp(-10*t)*(1-np.exp(-t*600))

def tick():
    t=t_axis(0.075)
    return filt_noise(len(t),4500,14000)*np.exp(-65*t)+0.3*np.sin(2*np.pi*2100*t)*np.exp(-70*t)

# instrument, source root MIDI, default volume/pan, generator, normalization
specs = [
    (1, 60, 48, 128, pluck, 0.76, 'GLASS PLUCK'),
    (2, 72, 52, 128, lead, 0.74, 'NEON REED'),
    (3, 36, 58, 128, bass, 0.84, 'DRIVE BASS'),
    (4, 60, 34, 128, pad, 0.70, 'SOFT CIRCUIT'),
    (5, 72, 42, 128, bell, 0.74, 'DATA BELLS'),
    (6, 60, 64, 128, kick, 0.92, 'KICK 808ish'),
    (7, 60, 55, 128, snare, 0.84, 'SNARE SNAP'),
    (8, 60, 34, 170, lambda:hat(False), 0.67, 'CLOSED HAT'),
    (9, 60, 30, 85, lambda:hat(True), 0.65, 'OPEN HAT'),
    (10,60, 30, 190, shaker, 0.66, 'SHAKER'),
    (11,60, 38, 110, crash, 0.72, 'CRASH+AIR'),
    (12,60, 34, 128, riser, 0.70, 'UPLINK RISER'),
    (13,60, 40, 128, stab, 0.72, 'CIRCUIT STAB'),
    (14,48, 48, 128, tom, 0.82, 'ELECTRIC TOM'),
    (15,60, 26, 180, tick, 0.56, 'TINY TICK'),
]
paths={}
for ins,root,vol,pan,gen,peak,name in specs:
    path=save_wav(f'{ins:02d}_{name.lower().replace(" ","_").replace("+","_")}',gen(),peak)
    paths[ins]=path

# ---------- Score ----------
# One row is a sixteenth note. 16 rows/bar, 64 rows/pattern, 16 patterns.
BARS=64
ROWS=BARS*16
events={ch:{} for ch in range(16)}
names=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
def nn(midi):
    return names[midi%12]+'-'+str(midi//12-1)
def add(ch,grow,note,ins,vol=64,pan=None):
